        if (!t.hasTag(ARRAY) || isReifiable(t)) {
            return;
        }
        ArrayType from = (ArrayType)t;
        boolean shouldWarn = false;
        switch (s.getTag()) {
            case ARRAY:
                ArrayType to = (ArrayType)s;
                shouldWarn = from.isVarargs() &&
                        !to.isVarargs() &&
                        !isReifiable(from);
                break;
            case CLASS:
                shouldWarn = from.isVarargs();
                break;
        }
        if (shouldWarn) {
            warn.warn(LintCategory.VARARGS);
